+/// A guard that tells all workers to quit if it is dropped while panicking.
+///
+/// Workers coordinate their termination with one another: a worker only stops
+/// waiting for more work once every other worker has also run out of work. A
+/// worker that dies from a panic never reports that it ran out of work, so
+/// without this, the remaining workers would wait for it forever.
+struct QuitOnPanic<'a>(&'a AtomicBool);
+
+impl Drop for QuitOnPanic<'_> {
+    fn drop(&mut self) {
+        if std::thread::panicking() {
+            self.0.store(true, AtomicOrdering::SeqCst);
+        }
+    }
+}
